// Defines the UTC reporting window. Single source of truth for every project.
// For a backfill, temporarily raise LOOKBACK_DAYS (e.g. 7) and run manually.
const LOOKBACK_DAYS = 1;

const now = new Date();
const end = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
const start = new Date(end.getTime() - LOOKBACK_DAYS * 86400000);
const iso = (d) => d.toISOString().slice(0, 19) + 'Z';

return [{
  json: {
    window_start: iso(start),
    window_end: iso(end),
    report_date: iso(start).slice(0, 10),
    lookback_days: LOOKBACK_DAYS,
    run_at: iso(now)
  }
}];

// Flattens every page of the Zendesk search export into one item per ticket,
// de-duplicates, and re-filters on exact UTC bounds (Zendesk search date
// handling can be timezone-sensitive, so we never trust it alone).
const cfg = $('P1 · Config').first().json;
const start = new Date(cfg.window_start).getTime();
const end = new Date(cfg.window_end).getTime();

const out = [];
const seen = new Set();
let sawResults = false;
let sawError = false;

for (const item of $input.all()) {
  const body = item.json || {};
  if (body.error || body.__error) sawError = true;
  if (Object.prototype.hasOwnProperty.call(body, 'results')) sawResults = true;
  const results = body.results || [];
  for (const t of results) {
    if (!t || !t.id) continue;
    const created = new Date(t.created_at).getTime();
    if (!(created >= start && created < end)) continue;
    if (seen.has(t.id)) continue;
    seen.add(t.id);
    out.push({ json: t });
  }
}

// Never return zero items: an empty branch would be skipped by n8n and the
// project would silently vanish from the report.
// Distinguish "quiet day" from "Zendesk call failed" - reporting fake zeros
// for a failed fetch would be worse than saying nothing.
if (!out.length) return [{ json: { __no_tickets: true, fetch_failed: (sawError || !sawResults) } }];
return out;

// Chunks ticket IDs into batches of 100 for /tickets/show_many.
// ids=0 is a deliberate no-op: Zendesk returns 200 with an empty array,
// which keeps the branch alive on a zero-ticket day.
const tickets = $('P1 · Flatten Tickets').all().map(i => i.json).filter(t => t && t.id);
const ids = tickets.map(t => t.id);
const SIZE = 100;

if (!ids.length) return [{ json: { chunk: 0, ids: '0', empty: true } }];

const out = [];
for (let i = 0; i < ids.length; i += SIZE) {
  out.push({ json: { chunk: i / SIZE, ids: ids.slice(i, i + SIZE).join(','), empty: false } });
}
return out;

// Thin per-branch packager: hands the shared Assemble node everything it needs
// for this project. Deliberately tiny so the heavy logic lives in ONE place.
// Prefix is literal, not derived - a dynamic $() lookup is not worth the risk.
const flat = $('P1 · Flatten Tickets').all();

return [{
  json: {
    cfg: $('P1 · Config').first().json,
    tickets: flat.map(i => i.json).filter(t => t && t.id),
    fetch_failed: flat.some(i => i && i.json && i.json.fetch_failed === true),
    meta: $input.all().map(i => i.json)
  }
}];

