const HIGHLIGHT_RULES = [
  'For each ticket you choose, return TWO fields.',
  'highlight must be the span copied verbatim from the ticket text you were given - character for character, in the original language, no paraphrasing, no correcting spelling, no ellipses of your own. This field is checked against the ticket, so it must match exactly.',
  'english must be that same span rendered in English. If the original span is already in English, repeat it exactly, character for character. If it is in any other language, translate it faithfully into natural English without adding, removing or softening meaning, and without translating email addresses, ticket numbers, product names or other identifiers.',
