// Attaches themes, quotes and feature highlights. Every highlight is verified
// to be a verbatim substring of the ticket it is attributed to - a paraphrase
// is discarded rather than shown next to a real customer's email address.
const readJson = (item) => {
  try {
    const parts = item.json.candidates[0].content.parts || [];
    const txt = parts.map(p => p.text || '').join('').replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
    return JSON.parse(txt);
  } catch (e) { return null; }
};
const projects = $('Apply Classification').all().map(i => i.json);
const jobs = $('Prep Bucket Digest').all().map(i => i.json);
const resp = $input.all();

const loose = (s) => String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]+/g, '');

const store = {};   // project -> {themes:{}, quotes:{}, features:{}}
const ensure = (pk) => (store[pk] = store[pk] || { themes: {}, quotes: {}, features: {} });

for (let i = 0; i < jobs.length; i++) {
  const job = jobs[i];
  if (!job) continue;
  const parsed = resp[i] ? readJson(resp[i]) : null;
  if (!parsed) continue;
  const s = ensure(job.project_key);

  if (job.job === 'digest') {
    s.themes[job.bucket_key] = parsed.theme ? String(parsed.theme).trim() : '';
    s.quotes[job.bucket_key] = Array.isArray(parsed.picks) ? parsed.picks : [];
  } else if (job.job === 'features') {
    for (const f of (Array.isArray(parsed.features) ? parsed.features : [])) {
      if (f && f.feature) s.features[String(f.feature)] = {
        id: String(f.id || ''), highlight: String(f.highlight || ''), english: String(f.english || '')
      };
    }
  }
}

return projects.map(p => {
  const s = store[p.project_key] || { themes: {}, quotes: {}, features: {} };

  // Ids are resolved WITHIN a bucket. A pick from another bucket - or an id the
  // model invented - is dropped rather than quoted under the wrong heading.
  const byBucket = {};
  for (const b of p.breakdown) {
    const map = byBucket[b.key] = {};
    for (const t of (p.grouped[b.key] || [])) map[t.id] = t;
  }

  // Verification always runs on the ORIGINAL-language span, because a
  // translation can never be a substring of the source. What gets displayed is
  // the English rendering; the verbatim span is only ever used to prove the
  // quote is real and not fabricated.
  const resolve = (id, highlight, english, scope) => {
    const t = scope[id];
    if (!t) return null;
    const h = String(highlight == null ? '' : highlight).replace(/\s+/g, ' ').trim();
    const en = String(english == null ? '' : english).replace(/\s+/g, ' ').trim();
    const ok = h.length > 0 && loose(t.full).indexOf(loose(h)) !== -1;
    const text = ok ? (en || h) : String(t.full || '').slice(0, Number(p.quote_chars) || 300);
    return {
      id: t.id, email: t.email, url: t.url, quote: text, verbatim: ok,
      translated: ok && !!en && loose(en) !== loose(h)
    };
  };

  const quotes = {};
  let discarded = 0;
  let translated = 0;
  for (const b of p.breakdown) {
    const picks = s.quotes[b.key] || [];
    const want = (p.quotas || {})[b.key] || 3;
    const seen = new Set();
    const out = [];
    for (const pk of picks) {
      const id = String((pk && pk.id) != null ? pk.id : '').trim();
      if (!id || seen.has(id)) continue;
      const r = resolve(id, pk.highlight, pk.english, byBucket[b.key] || {});
      if (!r) continue;
      if (!r.verbatim) discarded++;
      if (r.translated) translated++;
      seen.add(id);
      out.push(r);
      if (out.length >= want) break;
    }
    // top up if the model returned too few, so a populated bucket is never bare
    if (out.length < Math.min(want, (p.grouped[b.key] || []).length)) {
      for (const t of (p.grouped[b.key] || [])) {
        if (out.length >= want) break;
        if (seen.has(t.id)) continue;
        seen.add(t.id);
        out.push({ id: t.id, email: t.email, url: t.url,
                   quote: String(t.full || '').slice(0, Number(p.quote_chars) || 300),
                   verbatim: false, translated: false });
      }
    }
    quotes[b.key] = out;
  }

  const featureRows = (p.feature_rows || []).map(r => {
    const hit = s.features[r.label];
    const q = hit ? resolve(hit.id, hit.highlight, hit.english, byBucket.technical || {}) : null;
    if (q && q.translated) translated++;
    return Object.assign({}, r, { quote: q });
  });

  return { json: Object.assign({}, p, {
    themes: s.themes, quotes, feature_rows: featureRows,
    highlights_discarded: discarded, highlights_translated: translated
  }) };
});

